struct BasicOutputIterator {
    int* current;
    int& operator*() { return *current; }
    BasicOutputIterator& operator++() { 
        ++current; 
        return *this; 
    }
    BasicOutputIterator operator++(int) {
        BasicOutputIterator temp = *this;
        ++(*this);
        return temp;
    }
};

// Algorithm interaction pattern
while (input_it != end_it) {
    *output_it = *input_it; // Write through dereference
    ++input_it;
    ++output_it;            // Advance
}

// STL Inserter Trick (e.g., back_inserter)
// operator* returns iterator itself, allowing chaining with operator=
class BackInsertIter {
    Container* c;
public:
    BackInsertIter& operator*() { return *this; }
    BackInsertIter& operator=(const T& v) {
        c->push_back(v);
        return *this;
    }
    BackInsertIter& operator++() { return *this; }
    BackInsertIter operator++(int) { return *this; }
};
